def L6SIM2(plan, start=(2,8), t0=6, E=None):
    E=E or E6
    G={'D':(1,0),'U':(-1,0),'L':(0,-1),'R':(0,1)}
    guards={(6,4):'D',(6,10):'D',(10,4):'U',(10,6):'L',(12,4):'U',(12,6):'U'}
    def o1(t): return (4,6) if t%4==0 else ((0,6) if t%4==2 else (2,6))
    def o2(t):
        ph=(t-6)%12
        return (10, 2*ph if ph<=6 else 2*(12-ph))
    pos=start; t=t0; alive=set(guards); out=[]
    def path(a,b):
        if a==b: return [a]
        dr=(b[0]-a[0])//2 if b[0]!=a[0] else 0; dc=(b[1]-a[1])//2 if b[1]!=a[1] else 0
        return [a,(a[0]+dr,a[1]+dc),b]
    for mv in plan:
        t+=1
        if mv not in E.get(pos,{}): out.append((t,mv,'INVALID',pos)); return out
        (nxt,k)=E[pos][mv]
        pa=path(o1(t-1),o1(t)); pb=path(o2(t-1),o2(t))
        death=[]
        if nxt in (o1(t),o2(t)): death.append('Oland')
        if nxt in pa[1:] or nxt in pb[1:]: death.append('Opath')
        for g in list(alive):
            (gr,gc)=g; (dr,dc)=G[guards[g]]
            for d in range(1,k+1):
                if (gr+dr*d,gc+dc*d)==nxt: death.append('G'+str(g)); break
        cap=None
        if nxt in alive: death=[]; cap=nxt; alive.discard(nxt)
        out.append((t,mv,pos,'->',nxt,'k'+str(k),'cap',cap,'death',death,'O',(o1(t),o2(t))))
        if death: return out
        pos=nxt
    return out
